import{_ as e,o as n,c as t,ag as o}from"./chunks/framework.CrXGS008.js";const g=JSON.parse('{"title":"Uprawnienia","description":"","frontmatter":{},"headers":[],"relativePath":"pl/nay-lib/permissions.md","filePath":"pl/nay-lib/permissions.md"}'),d={name:"pl/nay-lib/permissions.md"};function i(s,a,r,c,p,l){return n(),t("div",null,[...a[0]||(a[0]=[o(`<h1 id="uprawnienia" tabindex="-1">Uprawnienia <a class="header-anchor" href="#uprawnienia" aria-label="Permalink to &quot;Uprawnienia&quot;">​</a></h1><p>Każda akcja Nayretis wymagająca uprawnień sprawdza <strong>scope</strong> (zakres uprawnień). Scope&#39;y nadaje się przez ACE, przez reguły zapisane w bazie danych albo w zakładce Uprawnienia w <code>/nay</code>.</p><h2 id="scope-y" tabindex="-1">Scope&#39;y <a class="header-anchor" href="#scope-y" aria-label="Permalink to &quot;Scope&#39;y&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scope</th><th>Daje dostęp do</th></tr></thead><tbody><tr><td><code>nay.admin</code></td><td>Wszystkiego: każdego skryptu, ustawień Nayretis, uprawnień, tokenów API, webhooków i dziennika zmian.</td></tr><tr><td><code>nay.config</code></td><td>Ustawień wszystkich skryptów.</td></tr><tr><td><code>nay.audit</code></td><td>Dziennika zmian.</td></tr><tr><td><code>&lt;resource&gt;.config</code></td><td>Ustawień jednego skryptu, na przykład <code>nay_car_wash.config</code>.</td></tr><tr><td><code>&lt;resource&gt;.&lt;name&gt;</code></td><td>Uprawnienia zadeklarowanego przez skrypt, wymienionego na jego stronie.</td></tr><tr><td><code>&lt;resource&gt;.*</code></td><td>Wszystkich scope&#39;ów jednego skryptu. Działa z regułami (<code>nay_grant</code>), nie z ACE.</td></tr></tbody></table><h2 id="przez-ace" tabindex="-1">Przez ACE <a class="header-anchor" href="#przez-ace" aria-label="Permalink to &quot;Przez ACE&quot;">​</a></h2><p>ACE na danym scope&#39;ie nadaje ten scope. Każdy scope nadawaj pełną nazwą (scope&#39;y z symbolem wieloznacznym, takie jak <code>nay_car_wash.*</code>, działają tylko jako reguły). W <code>server.cfg</code>:</p><div class="language-cfg vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cfg</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>add_ace group.admin nay.admin allow</span></span>
<span class="line"><span>add_ace group.mod nay_car_wash.config allow</span></span></code></pre></div><h2 id="przez-reguły" tabindex="-1">Przez reguły <a class="header-anchor" href="#przez-reguły" aria-label="Permalink to &quot;Przez reguły&quot;">​</a></h2><p>Reguły są zapisywane w bazie danych i mogą dotyczyć bezpośrednio jednego gracza. Reguła ma typ, identyfikator i scope. Dostępne typy:</p><ul><li><code>ace</code>: każdy gracz, któremu przysługuje dany obiekt ACE;</li><li><code>discord</code>, <code>steam</code>, <code>fivem</code>, <code>license</code>: jeden gracz, według identyfikatora.</li></ul><p>Z konsoli serwera:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>nay_grant license 1a2b3c4d5e6f nay.admin</span></span>
<span class="line"><span>nay_grant discord 123456789012345678 nay_car_wash.config</span></span>
<span class="line"><span>nay_revoke discord 123456789012345678 nay_car_wash.config</span></span>
<span class="line"><span>nay_rules</span></span></code></pre></div><p><code>nay_grant</code> i <code>nay_revoke</code> przyjmują <code>&lt;ace|discord|steam|fivem|license&gt; &lt;identifier&gt; &lt;scope&gt;</code>. <code>nay_rules</code> wyświetla wszystkie reguły z ich numerami.</p><p>W grze zakładka <strong>Uprawnienia</strong> w <code>/nay</code> (scope <code>nay.admin</code>) wyświetla, dodaje i usuwa te same reguły. Każda zmiana trafia do <a href="/pl/nay-lib/audit">dziennika zmian</a>.</p>`,14)])])}const u=e(d,[["render",i]]);export{g as __pageData,u as default};
